import json, re
from pathlib import Path
p=Path('/mnt/data/v19expand/data/core_v19.json')
data=json.loads(p.read_text(encoding='utf-8'))
data['version']='19.1.0-expanded-core'

# helper constructors
def vocab(id,g,en,fr,ex_de,ex_en,ex_fr,choices_en,choices_fr,fb_de=None,fb_en=None,fb_fr=None):
    return {
        'id':id,'type':'vocabulary_choice','german':g,
        'answer':{'en':en,'fr':fr},
        'choices':{'en':choices_en,'fr':choices_fr},
        'example_de':ex_de,
        'example':{'en':ex_en,'fr':ex_fr},
        'feedback':{
            'de':fb_de or f'„{g}“ wird in beruflichen Situationen häufig verwendet.',
            'en':fb_en or f'“{g}” is common in professional situations.',
            'fr':fb_fr or f'« {g} » est courant dans les situations professionnelles.'
        }
    }
def ap(id,sing,plural,article,ex_de,ex_en,ex_fr,fb_de,fb_en,fb_fr):
    return {'id':id,'type':'article_plural','singular':sing,'answer':plural,'article':article,'example_de':ex_de,'example':{'en':ex_en,'fr':ex_fr},'feedback':{'de':fb_de,'en':fb_en,'fr':fb_fr}}
def gap(id,prompt,answer,ex_de,ex_en,ex_fr,fb_de,fb_en,fb_fr,acc=None):
    return {'id':id,'type':'gap_fill','prompt':prompt,'answer':answer,'acceptable':acc or [answer],'example_de':ex_de,'example':{'en':ex_en,'fr':ex_fr},'feedback':{'de':fb_de,'en':fb_en,'fr':fb_fr}}
def mc(id,prompt,answer,choices,ex_de,ex_en,ex_fr,fb_de,fb_en,fb_fr):
    return {'id':id,'type':'multiple_choice','prompt':prompt,'answer':answer,'choices':choices,'example_de':ex_de,'example':{'en':ex_en,'fr':ex_fr},'feedback':{'de':fb_de,'en':fb_en,'fr':fb_fr}}

