mods['connectors']['items'].extend([
 mc('co009','Wähle den korrekten Satz.','Obwohl ich wenig Zeit habe, erledige ich die Aufgabe heute.',['Obwohl ich wenig Zeit habe, erledige ich die Aufgabe heute.','Obwohl ich habe wenig Zeit, erledige ich die Aufgabe heute.','Obwohl ich wenig Zeit habe, ich erledige die Aufgabe heute.'],'Obwohl ich wenig Zeit habe, erledige ich die Aufgabe heute.','Although I have little time, I will complete the task today.','Bien que j’aie peu de temps, je termine la tâche aujourd’hui.','Nach „obwohl“ steht das konjugierte Verb am Ende des Nebensatzes.','After obwohl, the conjugated verb goes to the end of the subordinate clause.','Après obwohl, le verbe conjugué va à la fin de la subordonnée.'),
 mc('co010','Wähle den korrekten Satz.','Ich rufe Sie an, falls sich der Termin ändert.',['Ich rufe Sie an, falls sich der Termin ändert.','Ich rufe Sie an, falls ändert sich der Termin.','Ich rufe Sie an, falls der Termin sich ändert sich.'],'Ich rufe Sie an, falls sich der Termin ändert.','I will call you if the appointment changes.','Je vous appelle si le rendez-vous change.','„falls“ leitet einen Nebensatz ein: Verb am Ende.','falls introduces a subordinate clause: verb at the end.','falls introduit une subordonnée : verbe à la fin.'),
 mc('co011','Wähle den korrekten Satz.','Da die Rechnung falsch ist, bitte ich um Korrektur.',['Da die Rechnung falsch ist, bitte ich um Korrektur.','Da ist die Rechnung falsch, bitte ich um Korrektur.','Da die Rechnung ist falsch, bitte ich um Korrektur.'],'Da die Rechnung falsch ist, bitte ich um Korrektur.','Since the invoice is wrong, I ask for a correction.','Comme la facture est incorrecte, je demande une correction.','„da“ funktioniert wie „weil“: Verb am Ende des Nebensatzes.','da works like weil: verb at the end of the subordinate clause.','da fonctionne comme weil : verbe à la fin.'),
 mc('co012','Wähle den korrekten Satz.','Ich habe die Datei gespeichert, bevor ich den Computer ausgeschaltet habe.',['Ich habe die Datei gespeichert, bevor ich den Computer ausgeschaltet habe.','Ich habe die Datei gespeichert, bevor habe ich den Computer ausgeschaltet.','Ich habe die Datei gespeichert, bevor ich habe den Computer ausgeschaltet.'],'Ich habe die Datei gespeichert, bevor ich den Computer ausgeschaltet habe.','I saved the file before I switched off the computer.','J’ai enregistré le fichier avant d’éteindre l’ordinateur.','„bevor“ leitet einen Nebensatz ein: finites Verb am Ende.','bevor introduces a subordinate clause: finite verb at the end.','bevor introduit une subordonnée : verbe conjugué à la fin.'),
 mc('co013','Wähle den korrekten Satz.','Nachdem ich die Unterlagen geprüft hatte, schickte ich die Antwort.',['Nachdem ich die Unterlagen geprüft hatte, schickte ich die Antwort.','Nachdem ich hatte die Unterlagen geprüft, schickte ich die Antwort.','Nachdem ich die Unterlagen geprüft hatte, ich schickte die Antwort.'],'Nachdem ich die Unterlagen geprüft hatte, schickte ich die Antwort.','After I had checked the documents, I sent the answer.','Après avoir vérifié les documents, j’ai envoyé la réponse.','Nach vorangestelltem Nebensatz steht das finite Verb im Hauptsatz direkt danach.','After an initial subordinate clause, the finite verb in the main clause comes immediately after it.','Après une subordonnée initiale, le verbe conjugué de la principale vient directement après.'),
 mc('co014','Wähle den korrekten Satz.','Ich lerne Deutsch, um bessere Chancen auf dem Arbeitsmarkt zu haben.',['Ich lerne Deutsch, um bessere Chancen auf dem Arbeitsmarkt zu haben.','Ich lerne Deutsch, um ich bessere Chancen habe.','Ich lerne Deutsch, um bessere Chancen haben.'],'Ich lerne Deutsch, um bessere Chancen auf dem Arbeitsmarkt zu haben.','I learn German in order to have better chances on the job market.','J’apprends l’allemand pour avoir de meilleures chances sur le marché du travail.','„um ... zu“ braucht einen Infinitiv mit „zu“.','um ... zu requires an infinitive with zu.','um ... zu exige un infinitif avec zu.'),
 mc('co015','Wähle den korrekten Satz.','Ich habe die Nachricht gelesen, aber ich habe noch nicht geantwortet.',['Ich habe die Nachricht gelesen, aber ich habe noch nicht geantwortet.','Ich habe die Nachricht gelesen, aber habe ich noch nicht geantwortet.','Ich habe die Nachricht gelesen, aber ich noch nicht geantwortet habe.'],'Ich habe die Nachricht gelesen, aber ich habe noch nicht geantwortet.','I read the message, but I have not answered yet.','J’ai lu le message, mais je n’ai pas encore répondu.','„aber“ verbindet Hauptsätze; die normale Verbposition bleibt erhalten.','aber connects main clauses; normal verb position is kept.','aber relie deux principales ; la position normale du verbe reste.'),
 mc('co016','Wähle den korrekten Satz.','Entweder wir verschieben den Termin, oder wir treffen uns online.',['Entweder wir verschieben den Termin, oder wir treffen uns online.','Entweder verschieben wir den Termin, oder treffen wir uns online.','Entweder wir den Termin verschieben, oder wir online treffen uns.'],'Entweder wir verschieben den Termin, oder wir treffen uns online.','Either we postpone the appointment, or we meet online.','Soit nous reportons le rendez-vous, soit nous nous rencontrons en ligne.','„entweder ... oder“ verbindet zwei Alternativen. Beide Hauptsätze brauchen klare Verbposition.','entweder ... oder connects two alternatives. Both main clauses need clear verb position.','entweder ... oder relie deux alternatives. Les deux principales exigent une position claire du verbe.'),
 mc('co017','Wähle den korrekten Satz.','Je besser die Vorbereitung ist, desto sicherer wird das Gespräch.',['Je besser die Vorbereitung ist, desto sicherer wird das Gespräch.','Je besser ist die Vorbereitung, desto sicherer wird das Gespräch.','Je besser die Vorbereitung ist, desto das Gespräch wird sicherer.'],'Je besser die Vorbereitung ist, desto sicherer wird das Gespräch.','The better the preparation is, the safer the interview becomes.','Plus la préparation est bonne, plus l’entretien est sûr.','„je ... desto“: Im je-Satz steht das Verb am Ende; im desto-Satz folgt das finite Verb früh.','je ... desto: in the je-clause the verb goes to the end; in the desto-clause the finite verb follows early.','je ... desto : dans la proposition avec je, le verbe va à la fin ; dans celle avec desto, le verbe conjugué suit tôt.'),
 mc('co018','Wähle den korrekten Satz.','Sowohl die Chefin als auch der Kollege nehmen teil.',['Sowohl die Chefin als auch der Kollege nehmen teil.','Sowohl die Chefin als auch der Kollege nimmt teil.','Sowohl die Chefin als auch nimmt der Kollege teil.'],'Sowohl die Chefin als auch der Kollege nehmen teil.','Both the manager and the colleague take part.','La cheffe et le collègue participent tous les deux.','Bei „sowohl ... als auch“ ist das Subjekt hier pluralisch: nehmen.','With sowohl ... als auch, the subject is plural here: nehmen.','Avec sowohl ... als auch, le sujet est ici pluriel : nehmen.'),
 mc('co019','Wähle den korrekten Satz.','Ich melde mich, sobald ich eine Rückmeldung bekomme.',['Ich melde mich, sobald ich eine Rückmeldung bekomme.','Ich melde mich, sobald bekomme ich eine Rückmeldung.','Ich melde mich, sobald ich bekomme eine Rückmeldung.'],'Ich melde mich, sobald ich eine Rückmeldung bekomme.','I will contact you as soon as I receive feedback.','Je vous contacte dès que je reçois un retour.','„sobald“ leitet einen Nebensatz ein: Verb am Ende.','sobald introduces a subordinate clause: verb at the end.','sobald introduit une subordonnée : verbe à la fin.'),
 mc('co020','Wähle den korrekten Satz.','Ich bin krank, deshalb bleibe ich heute zu Hause.',['Ich bin krank, deshalb bleibe ich heute zu Hause.','Ich bin krank, deshalb ich bleibe heute zu Hause.','Ich bin krank, deshalb heute zu Hause bleibe ich.'],'Ich bin krank, deshalb bleibe ich heute zu Hause.','I am sick, therefore I am staying at home today.','Je suis malade, donc je reste à la maison aujourd’hui.','„deshalb“ steht im Hauptsatzfeld; danach kommt das finite Verb.','deshalb occupies the first position of a main clause; the finite verb follows.','deshalb occupe la première position de la principale ; le verbe conjugué suit.')
])

