order_items=[
 mc('wo001','Wähle den natürlichsten Satz.','Morgen habe ich um neun Uhr ein Gespräch.',['Morgen habe ich um neun Uhr ein Gespräch.','Morgen ich habe um neun Uhr ein Gespräch.','Morgen um neun Uhr ich habe ein Gespräch.'],'Morgen habe ich um neun Uhr ein Gespräch.','Tomorrow I have an interview at nine o’clock.','Demain, j’ai un entretien à neuf heures.','Wenn ein Zeitwort am Anfang steht, kommt das finite Verb direkt danach.','When a time expression starts the sentence, the finite verb comes directly after it.','Quand une expression de temps commence la phrase, le verbe conjugué vient juste après.'),
 mc('wo002','Wähle den natürlichsten Satz.','Ich arbeite heute im Büro.',['Ich arbeite heute im Büro.','Ich heute arbeite im Büro.','Ich im Büro arbeite heute.'],'Ich arbeite heute im Büro.','I work in the office today.','Je travaille au bureau aujourd’hui.','Grundstellung: Subjekt + Verb + Zeit + Ort.','Basic order: subject + verb + time + place.','Ordre de base : sujet + verbe + temps + lieu.'),
 mc('wo003','Wähle den natürlichsten Satz.','Wir treffen uns nächste Woche in Düsseldorf.',['Wir treffen uns nächste Woche in Düsseldorf.','Wir treffen uns in Düsseldorf nächste Woche.','Wir nächste Woche treffen uns in Düsseldorf.'],'Wir treffen uns nächste Woche in Düsseldorf.','We meet in Düsseldorf next week.','Nous nous rencontrons à Düsseldorf la semaine prochaine.','Zeit steht normalerweise vor Ort: nächste Woche in Düsseldorf.','Time usually comes before place: nächste Woche in Düsseldorf.','Le temps vient généralement avant le lieu : nächste Woche in Düsseldorf.'),
 mc('wo004','Wähle den natürlichsten Satz.','Ich schicke Ihnen die Unterlagen morgen per E-Mail.',['Ich schicke Ihnen die Unterlagen morgen per E-Mail.','Ich schicke morgen per E-Mail Ihnen die Unterlagen.','Ich Ihnen schicke die Unterlagen morgen per E-Mail.'],'Ich schicke Ihnen die Unterlagen morgen per E-Mail.','I will send you the documents by email tomorrow.','Je vous envoie les documents demain par e-mail.','Das Dativpronomen/Objekt steht oft vor dem Akkusativobjekt.','The dative pronoun/object often comes before the accusative object.','Le pronom/objet au datif vient souvent avant l’objet à l’accusatif.'),
 mc('wo005','Wähle den natürlichsten Satz.','Heute kann ich leider nicht teilnehmen.',['Heute kann ich leider nicht teilnehmen.','Heute ich kann leider nicht teilnehmen.','Heute kann leider ich nicht teilnehmen.'],'Heute kann ich leider nicht teilnehmen.','Unfortunately I cannot take part today.','Aujourd’hui, je ne peux malheureusement pas participer.','Nach Vorfeld „Heute“ steht das finite Verb auf Position 2.','After the initial field Heute, the finite verb is in position 2.','Après le champ initial Heute, le verbe conjugué est en position 2.'),
 mc('wo006','Wähle den natürlichsten Satz.','Ich habe gestern wegen der Krankheit von zu Hause gearbeitet.',['Ich habe gestern wegen der Krankheit von zu Hause gearbeitet.','Ich habe wegen der Krankheit gestern von zu Hause gearbeitet.','Ich gestern habe wegen der Krankheit von zu Hause gearbeitet.'],'Ich habe gestern wegen der Krankheit von zu Hause gearbeitet.','I worked from home yesterday because of the illness.','Hier, j’ai travaillé de chez moi à cause de la maladie.','Eine brauchbare Reihenfolge ist Zeit vor Grund/Art/Ort.','A usable order is time before reason/manner/place.','Un ordre utile est temps avant cause/manière/lieu.'),
 mc('wo007','Wähle den natürlichsten Satz.','Bitte senden Sie mir die Rechnung bis Freitag.',['Bitte senden Sie mir die Rechnung bis Freitag.','Bitte senden mir Sie die Rechnung bis Freitag.','Bitte Sie senden mir die Rechnung bis Freitag.'],'Bitte senden Sie mir die Rechnung bis Freitag.','Please send me the invoice by Friday.','Veuillez m’envoyer la facture d’ici vendredi.','In der höflichen Aufforderung steht das Verb zuerst, dann „Sie“.','In a polite imperative, the verb comes first, then Sie.','Dans l’impératif poli, le verbe vient d’abord, puis Sie.'),
 mc('wo008','Wähle den natürlichsten Satz.','Im Anhang finden Sie die aktuelle Rechnung.',['Im Anhang finden Sie die aktuelle Rechnung.','Im Anhang Sie finden die aktuelle Rechnung.','Im Anhang die aktuelle Rechnung finden Sie.'],'Im Anhang finden Sie die aktuelle Rechnung.','You will find the current invoice in the attachment.','Vous trouverez la facture actuelle en pièce jointe.','Nach „Im Anhang“ steht das finite Verb direkt danach.','After Im Anhang, the finite verb follows immediately.','Après Im Anhang, le verbe conjugué suit directement.'),
 mc('wo009','Wähle den natürlichsten Satz.','Ich möchte mich für Ihre Hilfe bedanken.',['Ich möchte mich für Ihre Hilfe bedanken.','Ich möchte bedanken mich für Ihre Hilfe.','Ich für Ihre Hilfe möchte mich bedanken.'],'Ich möchte mich für Ihre Hilfe bedanken.','I would like to thank you for your help.','Je voudrais vous remercier pour votre aide.','Bei Modalverb/„möchte“ steht der Infinitiv am Ende.','With a modal verb/möchte, the infinitive goes to the end.','Avec un verbe modal/möchte, l’infinitif va à la fin.'),
 mc('wo010','Wähle den natürlichsten Satz.','Am Montag beginnt der neue Kurs.',['Am Montag beginnt der neue Kurs.','Am Montag der neue Kurs beginnt.','Am Montag beginnt neue der Kurs.'],'Am Montag beginnt der neue Kurs.','The new course begins on Monday.','Le nouveau cours commence lundi.','Vorfeld + finites Verb + Subjekt: Am Montag beginnt der Kurs.','Initial field + finite verb + subject.','Champ initial + verbe conjugué + sujet.'),
 mc('wo011','Wähle den natürlichsten Satz.','Ich habe die Datei gestern sorgfältig geprüft.',['Ich habe die Datei gestern sorgfältig geprüft.','Ich habe gestern sorgfältig die Datei geprüft.','Ich gestern habe die Datei sorgfältig geprüft.'],'Ich habe die Datei gestern sorgfältig geprüft.','I checked the file carefully yesterday.','J’ai vérifié soigneusement le fichier hier.','Im Perfekt steht das Partizip am Satzende.','In the perfect tense, the participle goes to the end.','Au parfait, le participe va à la fin.'),
 mc('wo012','Wähle den natürlichsten Satz.','Könnten Sie mir bitte kurz antworten?',['Könnten Sie mir bitte kurz antworten?','Könnten mir Sie bitte kurz antworten?','Könnten Sie bitte antworten mir kurz?'],'Könnten Sie mir bitte kurz antworten?','Could you please answer me briefly?','Pourriez-vous me répondre brièvement ?','Bei höflichen Fragen steht das finite Verb zuerst.','In polite questions, the finite verb comes first.','Dans les questions polies, le verbe conjugué vient d’abord.')
]

